1	import React, { useEffect, useState } from 'react';
2	import OtpAuth from '@salesforce/retail-react-app/app/components/otp-auth';
3	import { AuthModal } from '@salesforce/retail-react-app/app/hooks/use-auth-modal';
4	import { ZimmDrawer } from 'app/components/ui-kits/atoms/zimmDrawer';
5	import type { ZimmDrawerSize } from 'app/components/ui-kits/atoms/zimmDrawer';
6	import { breakpoints } from 'app/theme/foundation';
7	import { ZimmAuthDrawerContent } from 'app/components/ui-kits/organisms/zimmAuthDrawerContent';
8	import { ErrorFallback } from 'app/components/ui-kits/organisms/zimmAuthDrawerContent/errorFallback';
9	import { useWishlistAuthDrawer } from 'app/hooks/useWishlistAuthDrawer';
10	
11	export type ZimmWishlistAuthDrawerProps = {
12	  /**
13	   * Called after successful passwordless/OTP login. Not invoked for IDP (Apple/Google)
14	   * flows — those trigger a full browser redirect; the user lands back already logged in.
15	   */
16	  onAuthSuccess?: () => void;
17	  /** Identifies this mounted instance so a social-IDP round-trip resumes the right
18	   *  `onAuthSuccess` — required because more than one instance (e.g. header + PDP) can be
19	   *  mounted on the page the shopper returns to. Stable per call site, e.g. `'header-wishlist'`
20	   *  or `'pdp-wishlist'` — see `useWishlistAuthDrawer`'s own doc comment. */
21	  intentId: string;
22	  /** The single trigger element (button, icon-button, etc.). Its onClick is replaced by the
23	   *  auth-gate handler — call the original action via onAuthSuccess instead. */
24	  children: React.ReactElement;
25	};
26	
27	/**
28	 * Organism — wraps a single trigger element and gates its action behind auth.
29	 * If the customer is already registered the original onClick fires immediately.
30	 * If not, the Zimmermann auth drawer opens instead (passwordless email + optional social IDPs).
31	 *
32	 * Drop-in replacement for `withRegistration(Button)` on wishlist-specific entry points.
33	 * All SDK and auth logic lives in `useWishlistAuthDrawer` — this component is purely presentational.
34	 */
35	export const ZimmWishlistAuthDrawer = ({ onAuthSuccess, intentId, children }: ZimmWishlistAuthDrawerProps) => {
36	  const {
37	    isOpen,
38	    handleDrawerClose,
39	    handleTriggerClick,
40	    triggerRef,
41	    drawerTitle,
42	    description,
43	    emailValue,
44	    onEmailChange,
45	    onSendCode,
46	    onSignInWithApple,
47	    onSignInWithGoogle,
48	    isSocialEnabled,
49	    isPasswordlessEnabled,
50	    emailInputRef,
51	    onCreateAccount,
52	    isOtpAuthOpen,
53	    onOtpAuthClose,
54	    form,
55	    handlePasswordlessLogin,
56	    handleOtpVerification,
57	    registerModal,
58	  } = useWishlistAuthDrawer({ onAuthSuccess, intentId });
59	
60	  // SFCC-926 (Figma): wishlist auth drawer width is responsive — mobile full-width,
61	  // tablet (md–xl) 50% (large variant), desktop (≥ xl) 25% (small variant).
62	  // Both breakpoints from app/theme/foundation — same source as zimmDrawer.css.ts.
63	  // useEffect keeps window.matchMedia off the SSR render path (window not defined server-side).
64	  const [isTabletOrAbove, setIsTabletOrAbove] = useState(false);
65	  const [isDesktopOrAbove, setIsDesktopOrAbove] = useState(false);
66	  useEffect(() => {
67	    const tabletMq = window.matchMedia(`(min-width: ${breakpoints.md})`);
68	    const desktopMq = window.matchMedia(`(min-width: ${breakpoints.xl})`);
69	    setIsTabletOrAbove(tabletMq.matches);
70	    setIsDesktopOrAbove(desktopMq.matches);
71	    const onTablet = (e: MediaQueryListEvent) => setIsTabletOrAbove(e.matches);
72	    const onDesktop = (e: MediaQueryListEvent) => setIsDesktopOrAbove(e.matches);
73	    tabletMq.addEventListener('change', onTablet);
74	    desktopMq.addEventListener('change', onDesktop);
75	    return () => {
76	      tabletMq.removeEventListener('change', onTablet);
77	      desktopMq.removeEventListener('change', onDesktop);
78	    };
79	  }, []);
80	  // CodeRabbit (PR review): `mobile` was incorrectly applying the PDP-specific 58px backdrop
81	  // strip (SFCC-736 AC 9) to a utility drawer. `large` below md collapses to full-height
82	  // via ZimmDrawer's baseStyle without the strip.
83	  const drawerSize: ZimmDrawerSize = isDesktopOrAbove ? 'small' : 'large';
84	
85	  return (
86	    <>
87	      {React.cloneElement(React.Children.only(children), { onClick: handleTriggerClick })}
88	      <ZimmDrawer
89	        isOpen={isOpen}
90	        onClose={handleDrawerClose}
91	        size={drawerSize}
92	        title={drawerTitle}
93	        finalFocusRef={triggerRef}
94	        initialFocusRef={emailInputRef}
95	      >
96	        <ErrorFallback>
97	          <ZimmAuthDrawerContent
98	            description={description}
