import React, { useEffect, useState } from 'react';
import OtpAuth from '@salesforce/retail-react-app/app/components/otp-auth';
import { AuthModal } from '@salesforce/retail-react-app/app/hooks/use-auth-modal';
import { ZimmDrawer } from 'app/components/ui-kits/atoms/zimmDrawer';
import type { ZimmDrawerSize } from 'app/components/ui-kits/atoms/zimmDrawer';
import { breakpoints } from 'app/theme/foundation';
import { ZimmAuthDrawerContent } from 'app/components/ui-kits/organisms/zimmAuthDrawerContent';
import { ErrorFallback } from 'app/components/ui-kits/organisms/zimmAuthDrawerContent/errorFallback';
import { useWishlistAuthDrawer } from 'app/hooks/useWishlistAuthDrawer';

export type ZimmWishlistAuthDrawerProps = {
  /**
   * Called after successful passwordless/OTP login. Not invoked for IDP (Apple/Google)
   * flows — those trigger a full browser redirect; the user lands back already logged in.
   */
  onAuthSuccess?: () => void;
  /** Identifies this mounted instance so a social-IDP round-trip resumes the right
   *  `onAuthSuccess` — required because more than one instance (e.g. header + PDP) can be
   *  mounted on the page the shopper returns to. Stable per call site, e.g. `'header-wishlist'`
   *  or `'pdp-wishlist'` — see `useWishlistAuthDrawer`'s own doc comment. */
  intentId: string;
  /** The single trigger element (button, icon-button, etc.). Its onClick is replaced by the
   *  auth-gate handler — call the original action via onAuthSuccess instead. */
  children: React.ReactElement;
};

/**
 * Organism — wraps a single trigger element and gates its action behind auth.
 * If the customer is already registered the original onClick fires immediately.
 * If not, the Zimmermann auth drawer opens instead (passwordless email + optional social IDPs).
 *
 * Drop-in replacement for `withRegistration(Button)` on wishlist-specific entry points.
 * All SDK and auth logic lives in `useWishlistAuthDrawer` — this component is purely presentational.
 */
export const ZimmWishlistAuthDrawer = ({ onAuthSuccess, intentId, children }: ZimmWishlistAuthDrawerProps) => {
  const {
    isOpen,
    handleDrawerClose,
    handleTriggerClick,
    triggerRef,
    drawerTitle,
    description,
    emailValue,
    onEmailChange,
    onSendCode,
    onSignInWithApple,
    onSignInWithGoogle,
    isSocialEnabled,
    isPasswordlessEnabled,
    emailInputRef,
    onCreateAccount,
    isOtpAuthOpen,
    onOtpAuthClose,
    form,
    handlePasswordlessLogin,
    handleOtpVerification,
    registerModal,
  } = useWishlistAuthDrawer({ onAuthSuccess, intentId });

  // SFCC-926 (Figma): wishlist auth drawer width is responsive — mobile full-width,
  // tablet (md–xl) 50% (large variant), desktop (≥ xl) 25% (small variant).
  // Both breakpoints from app/theme/foundation — same source as zimmDrawer.css.ts.
  // useEffect keeps window.matchMedia off the SSR render path (window not defined server-side).
  const [isTabletOrAbove, setIsTabletOrAbove] = useState(false);
  const [isDesktopOrAbove, setIsDesktopOrAbove] = useState(false);
  useEffect(() => {
    const tabletMq = window.matchMedia(`(min-width: ${breakpoints.md})`);
    const desktopMq = window.matchMedia(`(min-width: ${breakpoints.xl})`);
    setIsTabletOrAbove(tabletMq.matches);
    setIsDesktopOrAbove(desktopMq.matches);
    const onTablet = (e: MediaQueryListEvent) => setIsTabletOrAbove(e.matches);
    const onDesktop = (e: MediaQueryListEvent) => setIsDesktopOrAbove(e.matches);
    tabletMq.addEventListener('change', onTablet);
    desktopMq.addEventListener('change', onDesktop);
    return () => {
      tabletMq.removeEventListener('change', onTablet);
      desktopMq.removeEventListener('change', onDesktop);
    };
  }, []);
  // CodeRabbit (PR review): `mobile` was incorrectly applying the PDP-specific 58px backdrop
  // strip (SFCC-736 AC 9) to a utility drawer. `large` below md collapses to full-height
  // via ZimmDrawer's baseStyle without the strip.
  const drawerSize: ZimmDrawerSize = isDesktopOrAbove ? 'small' : 'large';

  return (
    <>
      {React.cloneElement(React.Children.only(children), { onClick: handleTriggerClick })}
      <ZimmDrawer
        isOpen={isOpen}
        onClose={handleDrawerClose}
        size={drawerSize}
        title={drawerTitle}
        finalFocusRef={triggerRef}
        initialFocusRef={emailInputRef}
      >
        <ErrorFallback>
          <ZimmAuthDrawerContent
            description={description}
            emailValue={emailValue}
            onEmailChange={onEmailChange}
            onSendCode={onSendCode}
            onSignInWithApple={onSignInWithApple}
            onSignInWithGoogle={onSignInWithGoogle}
            onCreateAccount={onCreateAccount}
            socialEnabled={isSocialEnabled}
            passwordlessEnabled={isPasswordlessEnabled}
            initialFocusRef={emailInputRef}
          />
        </ErrorFallback>
      </ZimmDrawer>
      <AuthModal {...registerModal} />
      <OtpAuth
        isOpen={isOtpAuthOpen}
        onClose={onOtpAuthClose}
        form={form}
        handleSendEmailOtp={handlePasswordlessLogin}
        handleOtpVerification={handleOtpVerification}
        hideCheckoutAsGuestButton={true}
      />
    </>
  );
};

