import React from 'react';
import { describe, test, expect, vi, beforeEach } from 'vitest';
import { render, screen, fireEvent } from '@testing-library/react';
import { ChakraProvider } from '@chakra-ui/react';
import { MemoryRouter } from 'react-router-dom';
import theme from 'app/theme';
import { useSafeHref } from 'app/hooks/useSafeHref';
import { ZimmLink } from './index';

// ZimmIcon has a known Vitest breakage — SVG imports resolve to raw path strings, causing a
// top-level side effect on the SFCC icons barrel to throw. See testing.md Known gap.
vi.mock('app/components/ui-kits/atoms/zimmIcon', () => ({ ZimmIcon: () => null }));

// ZimmLink now calls useSafeHref() unconditionally (regional link prefixing) — mocked at its own
// module boundary (rather than reaching through to the real useMultiSite/MultiSiteContext chain,
// which has a known JSX-in-.js Vitest parse failure — see zimmNavItem/index.test.tsx) since this
// is our own hook and this is the smallest surface that keeps this suite scoped to ZimmLink's own
// contract, not useSafeHref's (covered by its own useSafeHref.test.ts).
vi.mock('app/hooks/useSafeHref', () => ({
  useSafeHref: vi.fn(),
}));

const mockUseSafeHref = vi.mocked(useSafeHref);

// Identity by default — the prefixing test below overrides this return value explicitly.
beforeEach(() => {
  mockUseSafeHref.mockReturnValue((href: string) => href);
});

const renderLink = (props: React.ComponentProps<typeof ZimmLink>) =>
  render(
    // MemoryRouter: an internal href now renders via react-router-dom's <Link> (regional link
    // prefixing fix), which throws without a Router ancestor.
    <MemoryRouter>
      <ChakraProvider theme={theme}>
        <ZimmLink {...props} />
      </ChakraProvider>
    </MemoryRouter>,
  );

describe('ZimmLink', () => {
  test('renders as <a> (role="link") when href is provided', () => {
    renderLink({ label: 'Shop Now', href: '/shop' });

    expect(screen.getByRole('link', { name: 'Shop Now' })).toHaveAttribute('href', '/shop');
    expect(screen.queryByRole('button')).not.toBeInTheDocument();
  });

  test('renders as <button> (role="button") when href is omitted', () => {
    const onClick = vi.fn();
    renderLink({ label: 'Open filters', onClick });

    expect(screen.getByRole('button', { name: 'Open filters' })).toBeInTheDocument();
    expect(screen.queryByRole('link')).not.toBeInTheDocument();
  });

  test('calls onClick when rendered as a button and clicked', () => {
    const onClick = vi.fn();
    renderLink({ label: 'Open filters', onClick });

    fireEvent.click(screen.getByRole('button', { name: 'Open filters' }));

    expect(onClick).toHaveBeenCalledTimes(1);
  });

  test('renders the label as visible text in anchor form', () => {
    renderLink({ label: 'Shop Now', href: '/shop' });

    expect(screen.getByRole('link', { name: 'Shop Now' })).toHaveTextContent('Shop Now');
  });

  test('renders the label as visible text in button form', () => {
    const onClick = vi.fn();
    renderLink({ label: 'Open filters', onClick });

    expect(screen.getByRole('button', { name: 'Open filters' })).toHaveTextContent('Open filters');
  });

  test('renders as <button> and no anchor when href is an unsafe javascript: URL', () => {
    renderLink({ label: 'XSS', href: 'javascript:alert(1)', onClick: vi.fn() });
    expect(screen.getByRole('button', { name: 'XSS' })).toBeInTheDocument();
    expect(screen.queryByRole('link')).not.toBeInTheDocument();
  });

  // Regression coverage for the regional-link bug: an internal href must be run through
  // useSafeHref() so it carries the current site/locale prefix, instead of a raw unprefixed
  // path that always falls back to the default site.
  test('runs an internal href through useSafeHref() to carry the current site/locale prefix', () => {
    mockUseSafeHref.mockReturnValue((href: string) => `/uk${href}`);

    renderLink({ label: 'New Arrivals', href: '/new-arrivals' });

    expect(screen.getByRole('link', { name: 'New Arrivals' })).toHaveAttribute('href', '/uk/new-arrivals');
  });

  test.each([
    ['https://instagram.com/zimmermann', 'https://instagram.com/zimmermann'],
    ['tel:+61255555555', 'tel:+61255555555'],
    ['mailto:help@zimmermann.com', 'mailto:help@zimmermann.com'],
    ['#size-guide', '#size-guide'],
  ])('leaves a non-internal href %s untouched by useSafeHref()', (href, expectedHref) => {
    // Would prove the bug if this ever got called for these hrefs.
    mockUseSafeHref.mockReturnValue((h: string) => `/uk${h}`);

    renderLink({ label: 'Link', href });

    expect(screen.getByRole('link', { name: 'Link' })).toHaveAttribute('href', expectedHref);
  });
});

// Spacing scale — source of truth: Figma node 2081:52901 (Design-Workspace > Spacing)
// Added to theme.space via extendTheme — Chakra's numeric defaults are preserved.
// Values are in rem so spacing scales with a user's root font-size / browser zoom
// (WCAG 1.4.4). Border widths (below) intentionally stay in px: hairline geometry
// shouldn't scale with zoom.

// prettier-ignore
export const spacing = {
  '3xs': '0.125rem', // 2px
  '2xs': '0.25rem',  // 4px
  xs:    '0.5rem',   // 8px
  s:     '0.75rem',  // 12px
  m:     '1rem',     // 16px
  l:     '1.25rem',  // 20px
  xl:    '1.5rem',   // 24px
  '2xl': '2rem',     // 32px
  '3xl': '2.5rem',   // 40px
  '4xl': '4rem',     // 64px
  '5xl': '5rem',     // 80px
  '6xl': '8rem',     // 128px
  '7xl': '10rem',    // 160px
} as const;

// Border widths — source of truth: Handover tokens/spacing.css (--zimm-border-width-default).
// Registered as theme.borderWidths; the CSS-var twin already exists in zimmTokens.ts.
export const borderWidths = {
  default: '1px',
} as const;

// Focus-ring outline offsets — hairline geometry, stays px like border widths above.
// `secondary` clears the 1px border on the secondary button variant (Handover
// button.md §focus) — the name describes that variant, not a generic scale step,
// since nothing else currently needs a third offset value.
export const focusRingOffsets = {
  default: '2px',
  secondary: '3px',
} as const;

